using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
public static class TeraEffectsBuilder {
 [Serializable] public class Effects {public Fx[] effects;}
 [Serializable] public class Fx {public string key,resource;public E[] emitters;}
 [Serializable] public class Key {public float t;public float[] value;}
 [Serializable] public class Burst {public float time;public int count;}
 [Serializable] public class E {public string name,kind,shaderKey,meshAsset,alignment;public bool localSpace;public float duration,delay;public int loops;public string[] unimplementedModules;public int[] subImages;public Burst[] bursts;public float[] lifetimeMin,lifetimeMax,rateMin,rateMax,sizeMin,sizeMax,locationMin,locationMax,velocityMin,velocityMax,accelerationMin,accelerationMax,rotationMin,rotationMax,rotationRateMin,rotationRateMax,alphaMin,alphaMax,colorMin,colorMax;public Key[] colors,sizes,velocities,rateCurveMin,rateCurveMax,lifetimeCurveMin,lifetimeCurveMax;}
 [Serializable] public class Mats {public Mat[] materials;}
 [Serializable] public class Mat {public string key,blend,texture;public float alphaCutoff;public Binding[] bindings;public string[] issues;}
 [Serializable] public class Binding {public string property,file;}
 const string Root="Assets/TeraCompanionLab/Effects/";
 static ParticleSystem.MinMaxCurve Range(float a,float b)=>new ParticleSystem.MinMaxCurve(Mathf.Min(a,b),Mathf.Max(a,b));
 static Vector3 Map(float[] v)=>new Vector3(-v[1],v[2],v[0])*.01f;
 static AnimationCurve Curve(Key[] keys,int component,float multiplier=1)=>new AnimationCurve(keys.Select(k=>new Keyframe(k.t,k.value[component]*multiplier)).ToArray());
 static readonly Dictionary<string,Mesh> metricMeshes=new Dictionary<string,Mesh>();
 static Mesh MetricMesh(string source){if(metricMeshes.TryGetValue(source,out var found))return found;var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(source);var filter=prefab?prefab.GetComponentInChildren<MeshFilter>():null;if(!filter||!filter.sharedMesh)throw new Exception("Effect mesh filter missing: "+source);var mesh=UnityEngine.Object.Instantiate(filter.sharedMesh);if(mesh.subMeshCount>1){var indices=mesh.triangles;mesh.subMeshCount=1;mesh.SetTriangles(indices,0);}var frame=filter.transform.localToWorldMatrix;mesh.vertices=mesh.vertices.Select(v=>frame.MultiplyPoint3x4(v)).ToArray();var normalFrame=frame.inverse.transpose;mesh.normals=mesh.normals.Select(n=>normalFrame.MultiplyVector(n).normalized).ToArray();mesh.RecalculateBounds();mesh.RecalculateTangents();Directory.CreateDirectory(Root+"MetricMeshes");var hash=System.Security.Cryptography.SHA256.Create().ComputeHash(System.Text.Encoding.UTF8.GetBytes(source));string key=BitConverter.ToString(hash).Replace("-","").Substring(0,20);string path=Root+"MetricMeshes/"+key+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,path);metricMeshes[source]=mesh;return mesh;}
 public static void Run(){try{Build();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Build(){Directory.CreateDirectory(Root+"Materials");Directory.CreateDirectory("Assets/TeraCompanionLab/Editor/Resources/TeraFX");var materialData=JsonUtility.FromJson<Mats>(File.ReadAllText(Root+"shader-bindings.json"));var mats=new Dictionary<string,Material>();var errors=new List<string>();foreach(var s in materialData.materials){var shader=Shader.Find("TeraCompanionLab/FX/"+s.key);if(!shader||ShaderUtil.ShaderHasError(shader)){errors.Add(s.key+": shader compilation failed");continue;}var mat=new Material(shader);foreach(var b in s.bindings){var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(b.file);if(!tex)errors.Add(s.key+": missing "+b.file);mat.SetTexture(b.property,tex);}if(!string.IsNullOrEmpty(s.texture))mat.SetTexture("_MainTex",AssetDatabase.LoadAssetAtPath<Texture2D>(s.texture));mat.SetFloat("_Cutoff",s.blend=="BLEND_Masked"?s.alphaCutoff:.0001f);mat.SetInt("_SrcBlend",(int)UnityEngine.Rendering.BlendMode.SrcAlpha);mat.SetInt("_DstBlend",(int)(s.blend=="BLEND_Additive"?UnityEngine.Rendering.BlendMode.One:UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha));string p=Root+"Materials/"+s.key+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(p);if(old){EditorUtility.CopySerialized(mat,old);UnityEngine.Object.DestroyImmediate(mat);mat=old;}else AssetDatabase.CreateAsset(mat,p);mats[s.key]=mat;}
 if(errors.Count>0){Directory.CreateDirectory("Migration/Validation/TeraEffects");File.WriteAllLines("Migration/Validation/TeraEffects/build-errors.txt",errors);throw new Exception("Effect material errors: "+errors.Count);}
 var fx=JsonUtility.FromJson<Effects>(File.ReadAllText(Root+"unity-effects.json"));int emitters=0;AssetDatabase.StartAssetEditing();try{foreach(var f in fx.effects){var root=new GameObject(f.resource);foreach(var e in f.emitters){var go=new GameObject(e.name);go.transform.SetParent(root.transform,false);var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.duration=Mathf.Max(.05f,e.duration);main.loop=e.loops==0;main.startDelay=Mathf.Max(0,e.delay);main.startLifetime=Range(Mathf.Max(.02f,e.lifetimeMin[0]),Mathf.Max(.02f,e.lifetimeMax[0]));if(e.lifetimeCurveMin!=null&&e.lifetimeCurveMin.Length>0)main.startLifetime=new ParticleSystem.MinMaxCurve(1,Curve(e.lifetimeCurveMin,0),Curve(e.lifetimeCurveMax,0));main.startSpeed=0;main.maxParticles=2048;main.scalingMode=ParticleSystemScalingMode.Hierarchy;main.simulationSpace=e.localSpace?ParticleSystemSimulationSpace.Local:ParticleSystemSimulationSpace.World;main.startSize3D=true;float unit=e.kind=="mesh"?1:.01f;float sx0=Mathf.Abs(e.sizeMin[0])*unit,sx1=Mathf.Abs(e.sizeMax[0])*unit;main.startSizeX=Range(sx0,sx1);main.startSizeY=Range(e.alignment=="PSA_Square"||e.sizeMin[1]==0?sx0:Mathf.Abs(e.sizeMin[1])*unit,e.alignment=="PSA_Square"||e.sizeMax[1]==0?sx1:Mathf.Abs(e.sizeMax[1])*unit);main.startSizeZ=Range(sx0,sx1);main.startRotation=Range(e.rotationMin[0]*Mathf.PI*2,e.rotationMax[0]*Mathf.PI*2);main.startColor=new ParticleSystem.MinMaxGradient(new Color(e.colorMin[0],e.colorMin[1],e.colorMin[2],e.alphaMin[0]),new Color(e.colorMax[0],e.colorMax[1],e.colorMax[2],e.alphaMax[0]));var emission=ps.emission;emission.rateOverTime=e.rateCurveMin!=null&&e.rateCurveMin.Length>0?new ParticleSystem.MinMaxCurve(1,Curve(e.rateCurveMin,0),Curve(e.rateCurveMax,0)):Range(e.rateMin[0],e.rateMax[0]);if(e.bursts!=null)emission.SetBursts(e.bursts.Select(b=>new ParticleSystem.Burst(b.time,(short)Mathf.Clamp(b.count,0,short.MaxValue))).ToArray());var loc0=Map(e.locationMin);var loc1=Map(e.locationMax);var shape=ps.shape;shape.enabled=(loc1-loc0).sqrMagnitude>1e-12f;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(Mathf.Abs(loc1.x-loc0.x),Mathf.Abs(loc1.y-loc0.y),Mathf.Abs(loc1.z-loc0.z));shape.position=(loc0+loc1)*.5f;if(!shape.enabled)go.transform.localPosition=loc0;
 var velocity=ps.velocityOverLifetime;velocity.enabled=true;velocity.space=e.localSpace?ParticleSystemSimulationSpace.Local:ParticleSystemSimulationSpace.World;var v0=Map(e.velocityMin);var v1=Map(e.velocityMax);velocity.x=Range(v0.x,v1.x);velocity.y=Range(v0.y,v1.y);velocity.z=Range(v0.z,v1.z);var force=ps.forceOverLifetime;force.enabled=true;force.space=ParticleSystemSimulationSpace.Local;var a0=Map(e.accelerationMin);var a1=Map(e.accelerationMax);force.x=Range(a0.x,a1.x);force.y=Range(a0.y,a1.y);force.z=Range(a0.z,a1.z);
 var color=ps.colorOverLifetime;color.enabled=true;var gradient=new Gradient();var chosen=Enumerable.Range(0,8).Select(i=>e.colors[(int)Math.Round(i*(e.colors.Length-1)/7.0)]).ToArray();gradient.SetKeys(chosen.Select(k=>new GradientColorKey(new Color(k.value[0],k.value[1],k.value[2]),k.t)).ToArray(),chosen.Select(k=>new GradientAlphaKey(Mathf.Clamp01(k.value[3]),k.t)).ToArray());color.color=gradient;var size=ps.sizeOverLifetime;size.enabled=true;size.separateAxes=true;size.x=new ParticleSystem.MinMaxCurve(1,Curve(e.sizes,0));size.y=new ParticleSystem.MinMaxCurve(1,Curve(e.sizes,1));size.z=new ParticleSystem.MinMaxCurve(1,Curve(e.sizes,2));var rotation=ps.rotationOverLifetime;rotation.enabled=true;rotation.z=Range(e.rotationRateMin[0]*Mathf.PI*2,e.rotationRateMax[0]*Mathf.PI*2);var renderer=ps.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=mats[e.shaderKey];renderer.renderMode=ParticleSystemRenderMode.Billboard;if(e.kind=="mesh"&&!string.IsNullOrEmpty(e.meshAsset)){var mesh=AssetDatabase.LoadAllAssetsAtPath(e.meshAsset).OfType<Mesh>().FirstOrDefault();if(mesh){renderer.renderMode=ParticleSystemRenderMode.Mesh;renderer.mesh=MetricMesh(e.meshAsset);}}
 if(e.kind=="ribbon"){var trails=ps.trails;trails.enabled=true;trails.mode=ParticleSystemTrailMode.Ribbon;trails.ribbonCount=1;trails.worldSpace=!e.localSpace;renderer.trailMaterial=mats[e.shaderKey];renderer.renderMode=ParticleSystemRenderMode.None;}if(e.subImages!=null&&e.subImages[0]*e.subImages[1]>1){var sheet=ps.textureSheetAnimation;sheet.enabled=true;sheet.numTilesX=e.subImages[0];sheet.numTilesY=e.subImages[1];sheet.frameOverTime=new ParticleSystem.MinMaxCurve(1,new AnimationCurve(new Keyframe(0,0),new Keyframe(1,1)));}emitters++;}PrefabUtility.SaveAsPrefabAsset(root,"Assets/TeraCompanionLab/Editor/Resources/TeraFX/"+f.key+".prefab");UnityEngine.Object.DestroyImmediate(root);}}finally{AssetDatabase.StopAssetEditing();}AssetDatabase.SaveAssets();Directory.CreateDirectory("Migration/Validation/TeraEffects");File.WriteAllText("Migration/Validation/TeraEffects/build.txt","Effects="+fx.effects.Length+" Emitters="+emitters+" Materials="+mats.Count+"\nSource modules still requiring exact implementation remain listed in unity-effects.json. Summon entries excluded.");Debug.Log("TERA_EFFECT_PREFABS_READY effects="+fx.effects.Length+" emitters="+emitters);}
}
